From 19b8cc9ef95ff79ee89185bd5004cf934dcd5401 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:25:02 +0100
Subject: [PATCH] applets/taskmanager: don't name-match audio streams of other
 tasks

A stream whose process belongs to a task was still matched by its
application name to other running tasks, so a Konsole child named Dolphin
put the audio indicator on Dolphin too. Such streams are now skipped.

BUG: 472539
---
 applets/taskmanager/qml/PulseAudio.qml | 11 ++++++++---
 applets/taskmanager/qml/Task.qml       |  2 +-
 2 files changed, 9 insertions(+), 4 deletions(-)

diff --git a/applets/taskmanager/qml/PulseAudio.qml b/applets/taskmanager/qml/PulseAudio.qml
index bbafcd8d0f..7e61ecf0c1 100644
--- a/applets/taskmanager/qml/PulseAudio.qml
+++ b/applets/taskmanager/qml/PulseAudio.qml
@@ -21,8 +21,12 @@ QtObject {
     property var pidMatches: new Set()

     // TODO Evict cache at some point, preferably if all instances of an application closed.
-    function registerPidMatch(appName: string) {
-        if (!hasPidMatch(appName)) {
+    function registerPidMatch(appName: string, streams: var) {
+        // Streams matched by PID belong to that task, don't also match them by name elsewhere.
+        const newStreams = streams.filter(stream => !stream.pidMatched);
+        newStreams.forEach(stream => stream.pidMatched = true);
+
+        if (!hasPidMatch(appName) || newStreams.length) {
             pidMatches.add(appName);

             // In case this match is new, notify that streams might have changed.
@@ -57,7 +61,7 @@ QtObject {
     }

     function streamsForAppName(appName: string): /*[QtObject]*/ var {
-        return findStreams("appName", appName);
+        return findStreamsFn(stream => stream.appName === appName && !stream.pidMatched);
     }

     function streamsForPid(pid: int): /*[QtObject]*/ var {
@@ -95,6 +99,7 @@ QtObject {
             readonly property int pid: model.Client?.properties["application.process.id"] ?? 0
             // Determined on demand.
             property int parentPid: -1
+            property bool pidMatched: false
             readonly property string appName: model.Client?.properties["application.name"] ?? ""
             readonly property string portalAppId: model.Client?.properties["pipewire.access.portal.app_id"] ?? ""
             readonly property bool muted: model.Muted
diff --git a/applets/taskmanager/qml/Task.qml b/applets/taskmanager/qml/Task.qml
index 90530078c5..c2c91e0b90 100644
--- a/applets/taskmanager/qml/Task.qml
+++ b/applets/taskmanager/qml/Task.qml
@@ -323,7 +323,7 @@ PlasmaCore.ToolTipArea {
         if (!streams.length) {
             streams = pa.streamsForPid(model.AppPid);
             if (streams.length) {
-                pa.registerPidMatch(model.AppName);
+                pa.registerPidMatch(model.AppName, streams);
             } else {
                 // We only want to fall back to appName matching if we never managed to map
                 // a PID to an audio stream window. Otherwise if you have two instances of
-- 
